#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Complex {
    pub re: i32,
    pub im: i32,
}

pub fn real_if_close(arr: Vec<Complex>, tol: i32) -> Vec<Complex> {
    // Assumption: tol is strictly positive.
    const EPS: i32 = 2;

    // Compute threshold in a wider type to avoid i32 overflow on multiplication.
    let thr: i64 = (tol as i64) * (EPS as i64);

    // Decide whether all imaginary parts are "close to zero".
    let all_close = arr
        .iter()
        .all(|c| (c.im as i64).abs() <= thr);

    if all_close {
        // Keep real parts unchanged; set imaginary parts to zero.
        arr.into_iter()
            .map(|c| Complex { re: c.re, im: 0 })
            .collect()
    } else {
        // Return unchanged.
        arr
    }
}